import XCTest
@testable import ODProtocolKit

/// Fixtures generated by py-opendisplay's `build_landing_url` (the layout's source of truth).
final class ODLandingLinkTests: XCTestCase {
    private let keyed = "https://opendisplay.org/l/?AQJQfhwAESIzRFVmd4iZqrvM3e7_AAM"
    private let keyless = "https://opendisplay.org/l/?AACrze8AAAAAAAAAAAAAAAAAAAAAAAA"
    private let key = Data([0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
                            0x88, 0x99, 0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF])

    func testParsesKeyedLink() throws {
        let link = try XCTUnwrap(ODLandingLink.parse(keyed))
        XCTAssertEqual(link.tagType, 0x0102)
        XCTAssertEqual(link.deviceID, Data([0x50, 0x7E, 0x1C]))
        XCTAssertEqual(link.deviceName, "OD507E1C")
        XCTAssertEqual(link.encryptionKey, key)
        XCTAssertEqual(link.manufacturerID, 3)
    }

    func testAllZeroKeyIsNil() throws {
        let link = try XCTUnwrap(ODLandingLink.parse(keyless))
        XCTAssertEqual(link.deviceName, "ODABCDEF")
        XCTAssertNil(link.encryptionKey)
    }

    func testToleratesRetypedForms() {
        let expected = ODLandingLink.parse(keyed)
        XCTAssertNotNil(expected)
        for variant in [
            "  \(keyed)\n",
            keyed.replacingOccurrences(of: "https://", with: "http://"),
            keyed.replacingOccurrences(of: "https://", with: ""),
            keyed.replacingOccurrences(of: "/l/?", with: "/l?"),
            keyed.replacingOccurrences(of: "opendisplay.org", with: "www.OpenDisplay.org"),
            keyed + "=",
        ] {
            XCTAssertEqual(ODLandingLink.parse(variant), expected, variant)
        }
    }

    func testRejectsForeignOrTruncatedLinks() {
        XCTAssertNil(ODLandingLink.parse("https://example.com/l/?AQJQfhwAESIzRFVmd4iZqrvM3e7_AAM"))
        XCTAssertNil(ODLandingLink.parse("https://opendisplay.org/x/?AQJQfhwAESIzRFVmd4iZqrvM3e7_AAM"))
        XCTAssertNil(ODLandingLink.parse("https://opendisplay.org/l/?AQJQfhwA"))
        XCTAssertNil(ODLandingLink.parse("https://opendisplay.org/l/"))
        XCTAssertNil(ODLandingLink.parse("not a link"))
    }

    func testNameMatching() throws {
        let link = try XCTUnwrap(ODLandingLink.parse(keyed))
        XCTAssertTrue(link.matches(advertisedName: "OD507E1C"))
        XCTAssertTrue(link.matches(advertisedName: "od507e1c"))
        XCTAssertTrue(link.matches(advertisedName: nil))
        XCTAssertFalse(link.matches(advertisedName: "OD000001"))
    }

    func testKeyEntryAcceptsHexAndLinks() throws {
        XCTAssertEqual(ODKeyEntry.parse("00112233445566778899aabbccddeeff"), .key(key))
        XCTAssertEqual(ODKeyEntry.parse(" 0x00112233445566778899AABBCCDDEEFF "), .key(key))
        XCTAssertEqual(ODKeyEntry.parse("00:11:22:33:44:55:66:77:88:99:aa:bb:cc:dd:ee:ff"), .key(key))
        XCTAssertEqual(ODKeyEntry.parse("0011 2233 4455 6677 8899 aabb ccdd eeff"), .key(key))
        let link = try XCTUnwrap(ODLandingLink.parse(keyed))
        XCTAssertEqual(ODKeyEntry.parse(keyed), .link(link))
        XCTAssertNil(ODKeyEntry.parse("00112233"))
        XCTAssertNil(ODKeyEntry.parse("zz112233445566778899aabbccddeeff"))
    }

    func testProtocolErrorsHaveReadableDescriptions() {
        XCTAssertEqual(ODProtocolError.authRequired.localizedDescription,
                       "This display is encrypted. Enter its key to continue.")
        XCTAssertFalse(ODProtocolError.encryptionNotConfigured.localizedDescription.contains("ODProtocolError"))
    }
}
